vec3 palette( float t ){
     vec3 a = vec3((sin(iTime*1.32456)),cos(iTime*0.76354),sin(iTime));
     vec3 b = vec3(.75,.25,.65);
     vec3 c = vec3(1.,1.,1.);
     vec3 d = vec3(0.263,0.416,0.557);
     return a+b*cos( 6.28318*(c*t+d) );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy*2.-1.;

    uv.x*=iResolution.x/iResolution.y;

    vec2 uv0=uv;

    vec3 fcol=vec3(0.);

    float f=25.;

    for (float i =1.0; i<f; i++){

        uv.x+=sin(uv.y*i-length(uv)+iTime)/i;

        uv.y+=cos(uv.x*i+length(uv)+iTime)/i;

        float d=length(uv)*exp(-length(uv0));

        d=sin(d*8.+iTime)/8.;

        d=abs(d);

        d=pow(0.01/d,1.2);

        vec3 col = sin(palette(length(uv)+iTime*0.4+i*0.4));;

        fcol+=col*d/(f-i);

    }

    fragColor = vec4(fcol,1.0);
}
